INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62593172', 62593172, 'analyze_legacy', 'Kab. Bandung', 'kabkota', 'DINAS PEKERJAAN UMUM DAN TATA RUANG', 'Tenaga Administrasi 4', 'Jasa Lainnya', 'Pengadaan Langsung', 'Jawa Barat, Bandung (Kab.)', 41909580, 'December 2025', 'APBD', 1, 1, '12 Bulan/orang', 'Pengelolaan Dokumentasi Proyek: Menyusun, mengelola, dan menyimpan dokumen administrasi yang terkait dengan proyek, baik dokumen fisik maupun digital. Koordinasi dan Penjadwalan: Menyusun jadwal kegiatan, rapat, dan pertemuan proyek, serta mengkoordinasikan berbagai kegiatan administratif untuk mendukung tim proyek. Penyusunan Laporan: Membuat laporan rutin yang mencakup kemajuan proyek, laporan keuangan, dan laporan administrasi lainnya yang diperlukan. Pengelolaan Komunikasi: Mengelola surat-menyurat dan komunikasi antara tim proyek dengan pihak terkait lainnya, serta menangani pengiriman informasi. Pengelolaan Sumber Daya dan Pengeluaran Administrasi: Memastikan bahwa perlengkapan kantor dan sumber daya administratif lainnya tersedia dengan cukup dan mengelola pengeluaran administratif. Dukungan Proyek dan Perizinan: Memberikan dukungan administratif untuk kebutuhan proyek, termasuk pengurusan perizinan, dokumentasi yang diperlukan, dan koordinasi dengan pihak-pihak eksternal.', 'Keahlian dan Kompetensi Manajemen Administrasi: Memiliki kemampuan dalam mengelola dan mengorganisir dokumen, surat-menyurat, dan laporan-laporan yang diperlukan dalam proyek atau kegiatan organisasi. Penggunaan Perangkat Lunak Administrasi: Mampu mengoperasikan perangkat lunak administrasi, seperti Microsoft Office (Word, Excel, PowerPoint), Google Workspace, dan perangkat lunak manajemen proyek atau sistem informasi lainnya. Pengarsipan dan Dokumentasi: Terampil dalam melakukan pengarsipan dokumen secara fisik maupun elektronik, serta memastikan bahwa dokumen dapat diakses dengan mudah dan sesuai dengan standar yang ditetapkan. Koordinasi dan Komunikasi: Mampu berkomunikasi dengan berbagai pihak di dalam dan luar organisasi untuk memastikan kelancaran informasi, termasuk berkoordinasi dengan tim proyek, klien, dan pihak ketiga. Manajemen Waktu: Memiliki kemampuan untuk mengatur waktu secara efisien, mengelola berbagai tugas administratif secara bersamaan, dan memenuhi tenggat waktu yang ditentukan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 21229);
