INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61836973', 61836973, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS TENAGA KERJA, TRANSMIGRASI, DAN ENERGI KOTA ADMINISTRASI JAKARTA TIMUR', 'Penyedia Jasa Lainnya Peorangan Teknisi Mekanik dan Listrik - Pembantu Instalator Energi', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Timur (Kota)', 210473679, 'December 2025', 'APBD', 1, 1, '1 Paket', 'a. Membantu melaksanakan penyambungan backup daya listrik pada penanggulangan bencana dan event di 5 (lima) wilayah Kota Administrasi dan Kabupaten Administrasi Kepulauan Seribu yang dikendalikan oleh Dinas Nakertransgi; b. Membantu melaksanakan perawatan, pemeliharaan dan pengoperasian Pembangkit Listrik Tenaga Surya (PLTS) yang dikendalikan oleh Suku Dinas Tenaga Kerja, Transmigrasi dan Energi Kota Administrasi Jakarta Timur; c. Membantu monitoring kesesuaian Harga Eceran Tertinggi (HET) LPG 3 kg di Agen dan Pangkalan wilayah Kota Administrasi Jakarta Timur; d. Membantu melaksanakan pendataan gedung milik Pemprov DKI Jakarta untuk audit energi. e. Membantu membuat pelaporan sesuai dengan lingkup tugasnya. f. Melaksanakan tugas kedinasan lainnya sesuai kebutuhan organisasi.', '1. Memenuhi ketentuan perundang-undangan untuk menjalankan kegiatan/usaha sesuai Klasifikasi Baku Lapangan Usaha Indonesia yang dibutuhkan seperti : - KBLI 96990 (Aktivitas Jasa Perorangan Lainnya YTDL) - Memiliki Nomor Induk Berusaha (NIB) yang masih berlaku 2. Warga Negara Indonesia (WNI) 3. Laki-Laki. 4. Memiliki KTP Elektronik 5. Memiliki NPWP Pribadi aktif dan telah memenuhi kewajiban perpajakan tahun pajak terakhir (SPT Tahunan 2023 atau 2024) 6. Umur Minimal 18 (delapan belas) tahun dan maksimal 56 (lima puluh enam) tahun pada saat pendaftaran 7. Diutamakan memiliki ijazah SMK Listrik / Sederajat. 8. Memiliki penilaian prestasi kerja minimal baik pada https://epjlp.jakarta.go.id . 9. Memiliki Akun SIKAP https://sikap.lkpp.go.id/login 10. Memiliki Akun SPSE https://spse.inaproc.id/jakarta/login b. Persyaratan Khusus Teknisi Listrik dan Mekanik – Pembantu Instalator Energi 1. Diutamakan memiliki SIM C, SIM A dan/atau SIM B1 yang masih berlaku. 2. Wajib memiliki sertifikat pelatihan di bidang Ketenagalistrikan operator pembangkit yang dikeluarkan dari Kementerian/Lembaga pemerintahan atau swasta. 3. Diutamakan memiliki sertifikat pelatihan teknis pengoperasian PLTD/PLTS yang dikeluarkan dari Kementerian/Lembaga pemerintahan. 4. Diutamakan memiliki sertifikat pelatihan teknis K3 yang dikeluarkan dari Kementerian/Lembaga pemerintahan. 5. Diutamakan Memiliki Sertifikat Keterampilan Kerja (SKK) atau Sertifikat Keterangan Terampil (SKT) bidang kelistrikan yang dikeluarkan dari Asosiasi/Lembaga yang berkompeten dan masih berlaku. 6. Surat Keterangan Catatan Kepolisian (SKCK) yang masih berlaku. 7. Surat Keterangan Sehat Jasmani yang masih berlaku dari Puskesmas atau RS Pemerintah. 8. Surat Keterangan Bebas Narkoba yang masih berlaku. 9. Memiliki pengalaman kerja di bidang energi dan ketenagalistrikan minimal 2 tahun dibuktikan dengan surat keterangan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 22298);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61825362', 61825362, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PANTI SOSIAL PERLINDUNGAN BINA KARYA HARAPAN MULIA', 'Pengadaan PJLP Petugas Teknisi Mekanik dan Listrik PSPBK HM', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Barat (Kota) | DKI Jakarta, Jakarta Utara (Kota)', 140315786, 'October 2025', 'APBD', 1, 1, '2 Orang x 13 Bulan', '1. Melaksanakan tugas mekanikal elektrikal dengan baik meliputi; a. Pemeliharaan peralatan Mekanikal Elektrikal gedung kantor di Panti Sosial; b. Melakukan perbaikan perlatan mekanikal elektrikal gedung kantor di Panti Sosial; c. Melakukan kerja bakti di lingkungan panti sosial; d.Memberi pelayanan kepada tamu dan masyarakat yang datang ke Panti Sosial. 2. Melaksanakan tugas kedinasan lainnya baik lisan maupun tulisan yang masih menjadi bagian pekerjaannya.', '1. Memastikan berfungsinya seluruh alat Elektronik dan Mesin milik Panti Sosial; 2. Memastikan seluruh alat eketronik dan mesin milik panti sosial dalam kondisi terawat; 3. Memastikan kembali berfungsinyaalat elektronik dan mesin milik kantor apabila terdapat kerusakan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 2, 22299);
