INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61835544', 61835544, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS  PERINDUSTRIAN, PERDAGANGAN, KOPERASI, USAHA KECIL DAN MENENGAH KABUPATEN - KEP. SERIBU', 'Pengadaan Peralatan dan Perlengkapan Kerja Kantor (Belanja Modal)', 'Barang', 'E-Purchasing', 'DKI Jakarta, Adm. Kepulauan Seribu (Kab.)', 30108288, 'March 2026', 'APBD', 1, 1, '8 Unit', 'Ruang lingkup pekerjaan pengadaan Belanja Modal Alat Penyimpan Perlengkapan Kantor meliputi seluruh proses penyediaan, pengiriman, pemasangan, serta serah terima barang berupa Rak Arsip Besi dan Filing Cabinet sesuai spesifikasi teknis berikut: 1. Penyediaan dan Pengadaan Barang Penyedia wajib menyediakan barang sebagai berikut: a. Rak Arsip Besi – 4 (empat) unit Dengan spesifikasi minimal: Dimensi: tinggi ± 213 cm, kedalaman ± 40 cm, lebar ± 90 cm Terdiri dari 4 (empat) compartement Material rangka kuat dan kokoh Finishing menggunakan powder coating Konstruksi stabil dan aman untuk penyimpanan arsip b. Filing Cabinet – 4 (empat) unit Dengan spesifikasi minimal: Jumlah laci: 2 (dua) laci Tipe: CO 2 (K.D.) / Knock Down System Dimensi: 470 mm (W) × 620 mm (D) × 719 mm (H) Material body dari plat baja Dilengkapi rel penggantung map (double rel plat baja) Laci dapat ditarik hingga 100% Sistem penguncian: central lock Finishing: Posphating & Powder Coating 2. Pengiriman Barang - Penyedia wajib mengirimkan seluruh barang ke lokasi kegiatan sesuai alamat yang tercantum dalam KAK/Dokumen Kontrak. - Barang harus dikemas dengan aman untuk menghindari kerusakan selama proses pengiriman. - Biaya pengiriman menjadi tanggung jawab penyedia. 3. Pemasangan dan Penempatan - Penyedia wajib melakukan pemasangan/merakit (knock-down) untuk unit filing cabinet. - Penyedia memastikan seluruh peralatan terpasang dengan baik, kokoh, dan siap digunakan. - Penyedia wajib menempatkan rak arsip dan filing cabinet sesuai arahan Pejabat/PPK pada lokasi kegiatan. 4. Pemeriksaan dan Uji Fungsi - Melakukan pengecekan fisik dan kualitas barang sesuai spesifikasi dalam KAK. - Melakukan uji fungsi pada filing cabinet, termasuk kelancaran rel laci dan sistem penguncian. - Memberikan laporan hasil pemeriksaan barang sebelum serah terima. 5. Serah Terima Barang - Menyerahkan seluruh barang dalam kondisi baru, tidak cacat, lengkap dengan komponen pendukung. - Menyerahkan dokumen pendukung meliputi: kartu garansi, manual penggunaan (jika ada), dan berita acara serah terima. - Penyedia wajib memberikan garansi minimal sesuai ketentuan pabrikan atau yang dipersyaratkan dalam dokumen pemilihan. 6. Ketentuan Tambahan - Barang yang diserahkan merupakan barang baru (bukan rekondisi/bekas). - Spesifikasi barang tidak boleh lebih rendah dari yang tercantum dalam KAK. - Penyedia wajib bertanggung jawab terhadap cacat mutu selama masa garansi. - Apabila ditemukan barang tidak sesuai spesifikasi, penyedia wajib mengganti tanpa biaya tambahan.', 'Spesifikasi sesuai di KAK 5.2.02.05.001.00004 Belanja Modal Alat Penyimpan Perlengkapan Kantor - 4 Unit Rak Arsip Besi Spesifikasi: +-H 213 x +-D.40 x +-W.90 cm, 4 compartement, Finishing Powder Coating - 4 Unit Filing Kabinet Spesifikasi: 2 Laci; Type : Co 2 (K.D.), Ukuran : 470 W X 620 D X 719 H (Mm), System Knock Down, Body Konstruksi Terbuat Dari Plat Baja, Terdiri Dari 2 Laci Dilengkapi Dengan Rel Penggantung Map, Double Rel Plat Baja, Laci Dapat Ditarik 100%, Kunci Sentral Lock, Proses Finishing Posphating & Powder Coating', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 22457);
