INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61819075', 61819075, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PANTI SOSIAL TRESNA WERDHA BUDI MULIA 4', 'Pengadaan PJLP Tenaga Penanganan Sosial Penyediaan Tenaga Pelayanan Kesejahteraan Sosial PSTW Budi Mulia 4 Tahun 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Timur (Kota)', 2245052576, 'November 2025', 'APBD', 1, 1, '32 Orang', 'a) Melakukan identifikasi awal Warga Binaan Sosial (WBS); b) Melakukan asesmen WBS; c) Melakukan pendampingan kebersihan diri WBS; d) Melakukan kegiatan yang mendukung kebersihan dan kerapian asrama dan lingkungan sekitar WBS; e) Melakukan pendampingan bagi WBS terhadap kebersihan dan kerapian asrama dan lingkungan sekitar dalam mengikuti kegiatan sehari-hari dalam mengikuti kegiatan sehari di panti seperti activity daily living, ibadah, makan, mandi, piket, apel, kerja bakti, belajar dan sebagainya; f) Melakukan pendampingan kegatan sehari hari/rutin bagi WBS diluar panti dengan melakukan pendampingan bagi WBS dalam mengikut kegiatan bimbingan pembinaan, pendidikan dan pelatihan diluar panti (sekolah, orientasi pengenalan, kursus, dan sebagainya); g) Memberikan motivasi dan pembinaan terkait perkembangan WBS secara rutin; h) Membuat catatan dan laporan perkembangan WBS meliputi perkembangan fisik, mental, sosial, sesuai dengan ketentuan yang berlaku; i) mencuci pakaian fasilitas warga binaan sosial yang memiliki kemampuan terbatas j) Melakukan rujukan dan koordinasi dengan peksos/psikolog/psikater/dokter dalam proses rehabilitasi dalam perkembangan psikososial WBS; k) Mengakomodir kebutuhan WBS untuk diteruskan ke Ka. Satpel/Ka. Subbag Tata Usaha; l) Melakukan tugas tambahan sesuai dengan kompetensinya (pekerja sosial, baby sitter dan sebagainya); m) Memberi pelayanan kepada tamu dan masyarakat yang datang ke panti sosial; n) Membuat laporan perkembangan WBS setiap hari; o) Membuat laporan pekerjaan harian; p) Melaksanakan tugas kedinasan lainnya baik lisan maupun tulisan yang masih menjadi bagian pekerjaannya', 'a) Melakukan identifikasi awal Warga Binaan Sosial (WBS); b) Melakukan asesmen WBS; c) Melakukan pendampingan kebersihan diri WBS; d) Melakukan kegiatan yang mendukung kebersihan dan kerapian asrama dan lingkungan sekitar WBS; e) Melakukan pendampingan bagi WBS terhadap kebersihan dan kerapian asrama dan lingkungan sekitar dalam mengikuti kegiatan sehari-hari dalam mengikuti kegiatan sehari di panti seperti activity daily living, ibadah, makan, mandi, piket, apel, kerja bakti, belajar dan sebagainya; f) Melakukan pendampingan kegatan sehari hari/rutin bagi WBS diluar panti dengan melakukan pendampingan bagi WBS dalam mengikut kegiatan bimbingan pembinaan, pendidikan dan pelatihan diluar panti (sekolah, orientasi pengenalan, kursus, dan sebagainya); g) Memberikan motivasi dan pembinaan terkait perkembangan WBS secara rutin; h) Membuat catatan dan laporan perkembangan WBS meliputi perkembangan fisik, mental, sosial, sesuai dengan ketentuan yang berlaku; i) mencuci pakaian fasilitas warga binaan sosial yang memiliki kemampuan terbatas j) Melakukan rujukan dan koordinasi dengan peksos/psikolog/psikater/dokter dalam proses rehabilitasi dalam perkembangan psikososial WBS; k) Mengakomodir kebutuhan WBS untuk diteruskan ke Ka. Satpel/Ka. Subbag Tata Usaha; l) Melakukan tugas tambahan sesuai dengan kompetensinya (pekerja sosial, baby sitter dan sebagainya); m) Memberi pelayanan kepada tamu dan masyarakat yang datang ke panti sosial; n) Membuat laporan perkembangan WBS setiap hari; o) Membuat laporan pekerjaan harian; p) Melaksanakan tugas kedinasan lainnya baik lisan maupun tulisan yang masih menjadi bagian pekerjaannya', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 22613);
