INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61838034', 61838034, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'DINAS PERHUBUNGAN', 'Penyelenggaraan Mudik dan Balik Gratis Angkutan Lebaran Provinsi DKI Jakarta Tahun 2026', 'Jasa Lainnya', 'Tender', 'DKI Jakarta, Jakarta Pusat (Kota)', 20229037639, 'December 2025', 'APBD', 0, 1, '1 Paket Pekerjaan', 'Penyelenggaran Mudik dan Balik Provinsi DKI Jakarta Tahun 2026 adalah menyediakan layanan transportasi berupa bus pengangkut penumpang dan truk pengangkut sepeda motor secara gratis bagi masyarakat pada periode Angkutan Lebaran Tahun 2026. Selain penyediaan sarana transportasi, kegiatan ini juga mencakup dukungan terhadap seluruh rangkaian penyelenggaraan, mulai dari tahap persiapan (sosialisasi dan pendaftran peserta), pelaksanaan arus mudik (seremonial keberangkatan serta monitoring perjalanan bus dan truk sampai tiba di kota tujuan), pelaksanaan arus balik (monitoring kendaraan dari kota asal hingga kembali ke Jakarta), hingga penyusunan laporan pelaksanaan kegiatan Mudik dan Balik Gratis Tahun 2026.', 'a. Bus gratis dari Jakarta menuju 20 (dua puluh) kota tujuan pada arus mudik; b. Truk pengangkut sepeda motor gratis menuju 6 (enam) kota tujuan pada arus mudik; c. Bus gratis dari 20 (dua puluh) kota asal menuju Jakarta pada arus balik; d. Truk pengangkut sepeda motor gratis dari 6 (enam) kota asal menuju Jakarta.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 22721);
