INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61801854', 61801854, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PUSAT HIGIENE PERUSAHAAN, KESELAMATAN DAN KESEHATAN KERJA', 'Belanja Jasa Tenaga Kebersihan', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 292392292, 'December 2025', 'APBD', 1, 1, '4 Orang', 'a. Melaksanakan pembersihan lantai dan ruangan; b. Melaksanakan pembersihan dinding keramik, gypsum, tembok maupun meubelair Laboratorium; c. Melakukan pembersihan meubelair; d. Melakukan pembersihan kaca gedung; e. Melakukan pembersihan langit-langit; f. Melakukan pembersihan toilet/WC termasuk closet dan urinoir; g. Melakukan pembersihan dan pembuangan sampah; h. Melakukan pembersihan dan perawatan taman i. Melakukan pembersihan halaman dan tempat parkir;Persyaratan kualifikasi administrasi/ legalitas meliputi:', '1. Memenuhi ketentuan peraturan perundang-undangan untuk menjalankan kegiatan/usaha. 2. Memiliki identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk (KTP/Paspor/Surat Keterangan Domisili Tinggal); 3. Memiliki status valid keterangan Wajib Pajak berdasarkan hasil konfirmasi status Wajib Pajak; 4. Surat Pernyataan Pakta Integritas. 5. Surat pernyataan yang ditandatangani Peserta yang berisi: • Tidak dikenakan Sanksi Daftar Hitam; • Keikutsertaannya tidak menimbulkan pertentangan kepentingan pihak yang terkait; • Tidak dalam pengawasan pengadilan dan/atau sedang menjalani sanksi pidana; dan • Tidak berstatus Aparatur Sipil Negara, kecuali yang bersangkutan mengambil cuti di luar tanggungan Negara. b. Persyaratan Kualifikasi Teknis Peserta Persyaratan kualifikasi teknis meliputi: 1. Berusia minimal 18 (delapan belas) tahun dan maksimal 56 (lima puluh enam) tahun 0 bulan 0 hari pada tanggal 1 Januari 2025; 2. Diutamakan memiliki pengalaman di bidangnya dibuktikan dengan Surat Keterangan Pengalaman Kerja/ Surat Perjanjian Kontrak Kerja; 3. Berkelakukan baik dan tidak pernah dihukum penjara atau kurungan berdasarkan putusan pengadilan yang telah mempunyai kekuatan hukum tetap karena melakukan suatu tindak pidana kejahatan (dibuktikan dengan fotokopi SKCK yang masih berlaku); 4. Sehat jasmani, rohani/mental dan tidak memiliki kelainan yang dapat mengganggu pelaksanaan pekerjaan (dibuktikan dengan Fotokopi Surat Keterangan Kesehatan dari dokter pemerintah) ; 5. Pendidikan minimal SLTP atau sederajat sesuai formasi yang dipersyaratkan 6. Tidak bertato atau bekas tato dan tidak ditindik atau bekas tindik telinga atau anggota tubuh lainnya; 7. Bebas Narkoba dibuktikan dengan fotokopi surat keterangan bebas narkoba yang masih berlaku; 8. Pelamar menandatangani surat pernyataan bermaterai Rp 10.000,- bahwa : • Tidak menuntut untuk diangkat menjadi CPNS/PNS atau Pegawai Pemerintah dengan Perjanjian Kerja (PPPK); • Tidak pernah diberhentikan dengan tidak hormat sebagai pegawai/karyawan pada perusahaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 23020);
