INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61837106', 61837106, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS TENAGA KERJA, TRANSMIGRASI, DAN ENERGI KOTA ADMINISTRASI JAKARTA TIMUR', 'Penyedia Jasa Lainnya Peorangan Teknisi Mekanik dan Listrik - Instalator Energi', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Timur (Kota)', 219160500, 'December 2025', 'APBD', 1, 1, '1 Paket', 'a. Melaksanakan penyambungan backup daya listrik pada penanggulangan bencana dan event di 5 (lima) wilayah Kota Administrasi dan Kabupaten Administrasi Kepulauan Seribu yang dikendalikan oleh Dinas Nakertransgi; b. Melaksanakan perawatan, pemeliharaan dan pengoperasian Pembangkit Listrik Tenaga Surya (PLTS) yang dikendalikan oleh Suku Dinas Tenaga Kerja, Transmigrasi dan Energi Kota Administrasi Jakarta Timur; c. Melaksanakan perawatan, pemeliharaan dan pengoperasian Pembangkit Listrik Tenaga Diesel (PLTD) dan Kendaraan Dinas Operasional (KDO) pendukung yang dikendalikan oleh Suku Dinas Tenaga Kerja, Transmigrasi dan Energi Kota Administrasi Jakarta Timur d. Melaksanakan monitoring kesesuaian Harga Eceran Tertinggi (HET) LPG 3 kg di Agen dan Pangkalan wilayah Kota Administrasi Jakarta Timur; e. Melaksanakan pendataan gedung milik Pemprov DKI Jakarta untuk audit energi. f. Membuat pelaporan sesuai dengan lingkup tugasnya. g. Melaksanakan tugas kedinasan lainnya sesuai kebutuhan organisasi.', '1. Diutamakan memiliki SIM C, SIM A dan/atau SIM B1 yang masih berlaku. 2. Wajib memiliki sertifikat pelatihan di bidang Ketenagalistrikan operator pembangkit yang dikeluarkan dari Kementerian/Lembaga pemerintahan atau swasta. 3. Diutamakan memiliki sertifikat pelatihan teknis pengoperasian PLTD/PLTS yang dikeluarkan dari Kementerian/Lembaga pemerintahan. 4. Diutamakan memiliki sertifikat pelatihan teknis K3 yang dikeluarkan dari Kementerian/Lembaga pemerintahan. 5. Diutamakan Memiliki Sertifikat Keterampilan Kerja (SKK) atau Sertifikat Keterangan Terampil (SKT) bidang kelistrikan yang dikeluarkan dari Asosiasi/Lembaga yang berkompeten dan masih berlaku. 6. Surat Keterangan Catatan Kepolisian (SKCK) yang masih berlaku. 7. Surat Keterangan Sehat Jasmani yang masih berlaku dari Puskesmas atau RS Pemerintah. 8. Surat Keterangan Bebas Narkoba yang masih berlaku. 9. Memiliki pengalaman kerja di bidang energi dan ketenagalistrikan minimal 4 tahun dibuktikan dengan surat keterangan. Berkas persyaratan khusus dilengkapi pada saat jadwal pemberkasan setelah dinyatakan memenuhi syarat.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 24531);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61840121', 61840121, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'DINAS KEPENDUDUKAN DAN PENCATATAN SIPIL', 'Belanja Jasa Konsultansi Berorientasi Bidang-Kependudukan', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Barat (Kota)', 90090000, 'December 2025', 'APBD', 1, 1, '1 Orang x 12 Bulan', 'a. Membantu dalam menyusun konsep MOU/Perjanjian Kerja Sama Pemanfaatan Data Kependudukan, Berita Acara maupun surat-surat dinas; b. Membantu menyusun rancangan kebijakan/produk hukum; c. Membantu menganalisa rancangan kebijakan/produk hukum; d. Mempersiapkan ruang kajian (reviu) berikut perangkat/peralatan; e. Membantu berkoordinasi dengan Perangkat Daerah/Unit Kerja Perangkat Daerah lainnya dalam kegiatan di Bidang Data dan Informasi; f. Membantu Scan/Digitalisasi dokumen reviu; g. Berkoordinasi dengan Unit Kerja lain dalam mengatur jadwal pembahasan dalam kegiatan naskah perjanjian kerjasama maupun kegiatan lainnya; h. Membantu dalam hal Monitoring kegiatan penyusunan naskah perjanjian kerjasama; i. Dapat membantu mendampingi dalam kegiatan penyusunan naskah akademis dan kegiatan lainnya; j. Membantu dalam mendapatkan informasi/keterangan /dokumen pendukung dalam kegiatan penyusunan naskah akademis dan raperda maupun kegiatan lain di organisasi; k. Membantu dalam menyusun laporan kegiatan; l. Membantu dalam hal pengetikan nota dinas/naskah akademis/raperda/PKS/dokumen lainnya; m. Membantu melaksanakan pengecekan/meneliti dokumen dalam penyusunan pengembalian dokumen ke Perangkat Daerah/Unit Kerja Perangkat Daerah; n. Menyusun dan merapikan dokumen; o. Membantu Scan/Digitalisasi dokumen; p. Membantu dalam hal pengarsipan dokumen; q. Membantu Kegiatan Dokumentasi; r. Melakukan pengecekan terhadap disposisi pimpinan; s. Membantu monitoring jadwal kegiatan di Bidang Data dan Informasi; t. Membantu kegiatan administrasi/tata naskah seperti surat menyurat, surat tugas, penyusunan checklist/kertas kerja, dsb; u. Membantu membuat rencana dan menyusun jadwal rapat; v. Membantu dalam hal administrasi dokumen-dokumen laporan; w. Membantu kegiatan lain yang dibutuhkan oleh organisasi', 'Senior Assistant Professional Staff Spesifikasi: Tenaga Sub Profesional (Jasa Konsultansi Perorangan Non Konstruksi); dengan kualifikasi: a) Pendidikan minimal S1 Hukum/ Administrasi Negara dengan IPK min 3.00; b) Mempunyai pengalaman dalam bidang pekerjaan hukum/administrasi hukum/penyusunan naskah legal/perjanjian/MoU minimal 2 (dua) tahun yang dibuktikan dengan surat pengalaman kerja', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 24532);
