INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61841816', 61841816, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PANTI SOSIAL BINA LARAS HARAPAN SENTOSA 2', 'Pengadaan Tenaga Penanganan Sosial Panti Sosial Bina Laras Harapan Sentosa 2 Tahun 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Timur (Kota)', 3998999901, 'November 2025', 'APBD', 1, 1, '57 Orang x 13 Bulan', 'a. Melakukan identifikasi awal dan asesmen Warga Binaan Sosial (WBS); b. Melakukan pendampingan kebersihan diri WBS; c. Melakukan kegiatan yang mendukung kebersihan dan kerapian asrama dan lingkungan sekitar WBS; d. Melakukan pendampingan bagi WBS terhadap kebersihan dan kerapian asrama dan lingkungan sekitar dalam mengikuti kegiatan sehari-hari dalam mengikuti kegiatan sehari di panti seperti activity daily living, ibadah, makan, mandi, piket, apel, kerja bakti, bimbingan dan sebagainya; e. Melakukan pendampingan kegiatan sehari hari/rutin bagi WBS diluar panti dengan melakukan pendampingan bagi WBS dalam mengikut kegiatan bimbingan pembinaan, pendidikan dan pelatihan diluar panti; f. Memberikan motivasi dan pembinaan terkait perkembangan WBS secara rutin; g. Membuat catatan dan laporan perkembangan WBS meliputi perkembangan fisik, mental, sosial, sesuai dengan ketentuan yang berlaku; h. Melakukan rujukan dan koordinasi dengan peksos/psikolog/psikater/dokter dalam proses rehabilitasi dalam perkembangan psikososial WBS; i. Mengajukan, melaksanakan, dan mengikuti CC; j. Mengakomodir kebutuhan WBS untuk diteruskan ke Ka. Satpel/Ka. Subbag Tata Usaha; k. Memberi pelayanan kepada tamu dan masyarakat yang datang ke panti sosial; l. Melaksanakan tugas kedinasan lainnya baik lisan maupun tulisan yang masih menjadi bagian pekerjaannya; m. Mencatat dan melaporkan kinerja harian secara online setiap akhir bulan berjalan dan menyerahkan dokumen cetak ke Ka Sub Bagian Tata Usaha maksimal tanggal 5 (lima) setiap bulannya.', '- Warga Negara Indonesia; - Bertakwa kepada Tuhan Yang Maha Esa dan taat kepada Pancasila, Undang-Undang Dasar Tahun 1945 serta Negara Kesatuan Republik Indonesia; - Berjenis kelamin perempuan atau laki-laki dengan usia paling rendah 18 tahun 0 bulan 0 hari dan paling tinggi 56 tahun 0 bulan 0 hari pada tanggal 1 Januari 2025 (sesuai Keputusan Gubernur Nomor 1095 Tahun 2022); - Pendidikan minimal lulusan SLTA/sederajat atau SLTP/sederajat yang sedang mengikuti Paket C, dibuktikan dengan surat keterangan; - Sanggup bekerja penuh waktu; - Bersedia ditugaskan di lingkungan kerja Panti Sosial Bina Laras Harapan Sentosa 2 dan diluar jam kerja;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 24594);
