INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61835370', 61835370, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS KOMUNIKASI, INFORMATIKA DAN STATISTIK KOTA - JAKTIM', 'PJLP Network Administrator Kominfotik Jakarta Timur', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Timur (Kota)', 137688525, 'December 2025', 'APBD', 1, 1, '1 orang x 13 Bulan', 'a. Membantu Kepala Seksi Infrastruktur Digital melakukan identifikasi kebutuhan pembangunan Infrastruktur Teknologi Informatika; b. Melakukan monitoring operasional seluruh perangkat jaringan; c. Melakukan monitoring penggunaan/pemakaian bandwidth Internet/ intranet serta melakukan identifikasi kebutuhan perangkat dan sumber daya; d. Memberikan petunjuk serta arahan teknis kepada Teknisi Jaringan dalam lingkupnya; e. Melakukan pencadangan (backup) serta pemulihan (restore) berkala, konfigurasi dan memberikan solusi pada kerusakan hardware, software dan perangkat inti (core) jaringan serta server; f. Mengembangkan dan mengelola management keamanan jaringan intranet dan internet; g. Memeriksa pelanggaran keamanan dalam penggunaan jaringan; h. Menentukan standarisasi instalasi aplikasi pada server serta pada user; i. Memastikan pembaharuan pada software/perangkat (Update dan Upgrade); j. Melaksanakan tugas lain yang diperintahkan Pimpinan;dan k. Menyusun laporan dan dokumentasi pekerjaan berkala.', '1.Pendidikan minimal D3 jurusan bidang komputer/ informatika;2.Memiliki keahlian dalam bidang IT/ komputer/ jaringan internet;3.Pengalaman kerja di instansi pemerintahan minimal 3 tahun;4.Memiliki kemampuan teknis lanjutan penggunaan dan penanganan perangkat jaringan Cisco, Mikrotik, Ubiquiti, Ruijie, Microsoft Server atau CentOS dan teknologi virtualisasi serta perangkat server;5.Visioner dan mengikuti perkembangan teknologi perangkat keras dan perangkat lunak;6.Mempunyai kemampuan komunikasi yang baik;7.Memiliki sertifikat Komputer/Jaringan;8.Memiliki Surat Izin Mengemudi yang masih berlaku yaitu SIM C (nilai tambah apabila juga memiliki SIM A);9.Memiliki kendaraan bermotor.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 24602);
