INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61841351', 61841351, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PANTI SOSIAL BINA LARAS HARAPAN SENTOSA 2', 'Pengadaan Tenaga Teknisi Mekanik dan Listrik Panti Sosial Bina Laras Harapan Sentosa 2 Tahun 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Timur (Kota)', 140315786, 'November 2025', 'APBD', 1, 1, '2 Orang x 13 Bulan', 'Ruang lingkup pekerjaan meliputi: 1. Memelihara peralatan mekanikal elektrikal Panti Sosial lingkup Dinas Sosial Provinsi DKI Jakarta; 2. Memelihara instalasi telepon dan jaringan internet/kabel; 3. Memperbaiki peralatan mekanikal elektrikal Panti Sosial lingkup Dinas Sosial Provinsi DKI Jakarta; 4. Memperbaiki kerusakan kecil atas gedung dan sarana prasarana panti; 5. Memperbaiki lainnya atas perintah Pimpinan sebagai penunjang operasional layanan panti; 6. Menyiapkan sound system pada Ruang Rapat, saat Apel Pegawai, serta kegiatan panti yang membutuhkan pengeras suara; 7. Memberi pelayanan kepada tamu dan masyarakat yang datang ke kantor; 8. Mengecek berkala tabung APAR; 9. Mengoperasikan peralatan elektronik saat kegiatan. 10. Menyimpan dan merapikan perkakas kerja. 11. Memastikan seluruh peralatan elektronik off; 12. Melaksanakan koordinasi dengan petugas dalam perbaikan sarpras. 13. Melakukan pendampingan bagi WBS dalam mengikuti kegiatan sehari-hari di panti seperti activity daily living, ibadah, makan, kerja bakti, bimbingan fisik, silabi dan sebagainya sesuai dengan jadwal harian WBS; 14. Melaksanakan tugas kedinasan lainnya baik lisan maupun tulisan yang masih menjadi bagian pekerjaannya. 15. Mencatat dan melaporkan kinerja harian secara online setiap akhir bulan berjalan dan menyerahkan dokumen cetak ke Ka Sub Bagian Tata Usaha maksimal tanggal 5 (lima) setiap bulannya', '- Warga Negara Indonesia; - Bertakwa kepada Tuhan Yang Maha Esa dan taat kepada Pancasila, Undang-Undang Dasar Tahun 1945 serta Negara Kesatuan Republik Indonesia; - Berjenis kelamin perempuan atau laki-laki dengan usia paling rendah 18 tahun 0 bulan 0 hari dan paling tinggi 56 tahun 0 bulan 0 hari pada tanggal 1 Januari 2025 (sesuai Keputusan Gubernur Nomor 1095 Tahun 2022); - Pendidikan minimal lulusan SLTA/sederajat atau SLTP/sederajat yang sedang mengikuti Paket C, dibuktikan dengan surat keterangan; - Sanggup bekerja penuh waktu; - Bersedia ditugaskan di lingkungan kerja Panti Sosial Bina Laras Harapan Sentosa 2 dan diluar jam kerja;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 24702);
