INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63327664', 63327664, 'analyze_legacy', 'Kota Semarang', 'kabkota', 'DINAS KESEHATAN', 'Belanja Modal Kursi Rapat BLUD PUSKESMAS GAYAMSARI', 'Barang', 'E-Purchasing', 'Jawa Tengah, Semarang (Kota)', 24750000, 'August 2026', 'BLUD', 1, 1, '55 UNIT', 'Belanja Modal Kursi Rapat BLUD PUSKESMAS GAYAMSARI', 'Rangka/Kaki: Umumnya menggunakan bahan yang kokoh seperti besi, baja tahan karat, atau kayu solid untuk stabilitas. Banyak model memiliki kaki berbentuk U (model kantilever) atau empat kaki standar. Dudukan dan Sandaran: Dilapisi dengan busa empuk, seringkali menggunakan bahan kain (fabric), kulit sintetis (oscar), atau vinyl) untuk kemudahan perawatan dan penampilan profesional. Ergonomi: Walaupun statis, kursi rapat yang baik memiliki sandaran punggung yang mendukung postur tubuh alami, mengurangi tekanan pada punggung bagian bawah. Beberapa model mungkin memiliki sedikit kemiringan ke belakang untuk kenyamanan bersandar. Portabilitas & Penyimpanan: Banyak kursi rapat dirancang agar dapat ditumpuk (stackable), memungkinkan penyimpanan yang efisien saat ruang rapat digunakan untuk keperluan lain. Sandaran Tangan (Armrest): Terkadang dilengkapi dengan sandaran tangan tetap (bukan yang dapat disesuaikan) untuk dukungan tambahan. Dimensi Standar Dimensi kursi rapat yang ergonomis dan nyaman cenderung mengikuti standar tertentu, menurut beberapa sumber: Tinggi Dudukan: Sekitar 40 - 55 cm dari lantai. Lebar Dudukan: Sekitar 45 - 50 cm. Kedalaman Dudukan: Sekitar 40 - 45 cm agar paha tertopang dengan baik. Tinggi Sandaran: Sekitar 50 - 60 cm.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 28517);
