INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61856748', 61856748, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PUSAT DATA DAN INFORMASI CIPTA KARYA, TATA RUANG DAN PERTANAHAN', 'Tenaga Sub Profesional - Senior Assistant Professional Staff (Pengelolaan Kearsipan dan Digitalisasi Arsip Dokumen Teknis dan Perizinan Tata Ruang dan Bangunan)', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 90090000, 'November 2025', 'APBD', 1, 1, '1 Orang x 12 Bulan', 'Ruang lingkup pekerjaan Kegiatan Pengelolaan Digitalisasi Arsip Dokumen Teknis dan Perizinan Tata Ruang dan Bangunan (Senior Assistant Professional Staff) adalah sebagai berikut : a. Bertanggung jawab dalam tim dalam menjalankan dan mengelola sebuah proyek dalam kegiatan digitalisasi arsip; b. Membuat jadwal pekerjaan memberikan tugas sampai dengan memantau dan mengendalikan hasil pekerjaan tim; c. Memahami mekanisme pengelolaan kearsipan; d. Memahami kebutuhan kegiatan digitalisasi yang efektif dan efesien untuk mencapai target capaian; e. Menemukan solusi untuk kebutuhan pencapaian tujuan; f. Memberikan dukungan mengupdate data hasil scan di lingkungan kerja Pusat Data dan Informasi Cipta Karya, Tata Ruang dan Pertanahan; g. Melakukan membuat Analisa terhadap permasalahan; h. Melaporkan dan mempertanggung jawabkan pelaksanaan tugas; i. Berkonsultasi dengan tim dan membantu tenaga ahli mendefiniskan dan menyelesaikan masalah dalam menjalankan program-program computer; j. Melaksanakan tugas lainnya yang ditetapkan oleh pimpinan/atasan sesuai kewenangan.', 'Spesifikasi Teknis Kegiatan Pengelolaan Digitalisasi Arsip Dokumen Teknis dan Perizinan Tata Ruang dan Bangunan (Senior Assistant Professional Staff) ini adalah: a. Memahami mekanisme pengelolaan kearsipan; b. Melakukan identifikasi dan pemetaan jenis arsip dokumen teknis dan perizinan (IMB, SLF, KRK); c. Memastikan kelengkapan setiap arsip sebelum dan sesudah digitalisasi; d. Menguasai dan Mengunggah arsip digital ke sistem ArcGis..', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 28716);
