INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61849561', 61849561, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS KOMUNIKASI, INFORMATIKA DAN STATISTIK KOTA - JAKTIM', 'PJLP Fotografer Intermediate Kominfotik Jakarta Timur', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Timur (Kota)', 230127300, 'December 2025', 'APBD', 1, 1, '2 orang x 13 bulan', '"Melakukan pengambilan gambar/foto (dan video apabila diperlukan) yang ditugaskan; Menulis berita sesuai dengan kaidah jurnalistik; Melakukan wawancara sebagai pendukung berita apabila diperlukan; Melakukan koordinasi dengan penyelenggara kegiatan yang akan diberitakan; Menginventarisir dan menyimpan hasil gambar/foto (dan video apabila ada) ke media penyimpanan computer atau server secara rapi dan terstruktur; Melakukan Koordinasi dengan penyelenggara kegiatan; Melaksanakan tugas lainnya sesuai perintah/permintaan baik tertulis maupun lisan dari staf dan/atau Kepala Seksi Komunikasi dan Informasi Publik; Bertanggung jawab untuk menjaga perangkat keras yang digunakan dalam menunjang proses pengambilan gambar/foto dan pemberitaan; Bertanggung jawab terhadap keseluruhan proses pengambilan gambar/foto dan pemberitaan; Membuat laporan kegiatan kerja."', '"Pendidikan minimal D3, jurusan yang relevan, atau memiliki sertifikasi keahlian yang terkait; Memiliki keahlian mengoperasikan, menjaga dan memelihara kamera foto; Memiliki keahlian mengambil gambar foto/video yang baik dengan framing, layouting, dan penyesuaian lighting; Memiliki kemampuan penulisan berita, editing dan mengoperasikan drone menjadi nilai tambah; Memiliki kreativitas tinggi serta memahami tren sosial terkini; Memiliki pengalaman kerja di bidang Pemerintahan; Memiliki sertifikat sesuai dibidangnya; Mempunyai kemampuan Komunikasi yang baik; Menguasai area penugasan yaitu Kota Administrasi Jakarta Timur"', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 29731);
