INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63325777', 63325777, 'analyze_legacy', 'Kota Semarang', 'kabkota', 'DINAS KESEHATAN', 'Belanja Modal Monitor BLUD PUSKESMAS GAYAMSARI', 'Barang', 'E-Purchasing', 'Jawa Tengah, Semarang (Kota)', 4000000, 'March 2026', 'BLUD', 1, 1, '2 UNIT', 'Belanja Modal Monitor BLUD PUSKESMAS GAYAMSARI', 'esolusi Jumlah piksel horizontal dan vertikal (misalnya, Full HD/1080p, QHD/1440p, 4K/UHD). Resolusi lebih tinggi menghasilkan gambar yang lebih tajam dan detail. Ukuran Layar Diukur secara diagonal dalam inci. Ukuran 24-27 inci sering dianggap ideal untuk tugas kantor dan gaming. Tipe Panel IPS menawarkan akurasi warna superior dan sudut pandang lebar, ideal untuk pekerjaan kreatif. VA memberikan kontras tinggi (hitam lebih pekat), cocok untuk hiburan dan gaming. TN memiliki waktu respons tercepat, pilihan utama untuk gaming kompetitif. Refresh Rate Frekuensi layar memperbarui konten per detik, diukur dalam Hertz (Hz). Standar adalah 60Hz; gaming monitor menawarkan 144Hz, 180Hz, atau 240Hz untuk gerakan yang lebih mulus. Response Time Kecepatan piksel berubah warna, diukur dalam milidetik (ms). Waktu respons yang rendah (misalnya, 1ms atau kurang) mengurangi motion blur dan ghosting, penting untuk gaming cepat. Konektivitas Pastikan ketersediaan port yang sesuai dengan perangkat Anda, seperti HDMI, DisplayPort, atau USB-C. Fitur Ergonomis Dudukan yang dapat diatur ketinggian, kemiringan (tilt), putar (swivel), dan poros (pivot) membantu memastikan posisi yang nyaman dan sehat saat penggunaan jangka panjang.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 29837);
